// ── Run Config ───────────────────────────────────────────────────────────────
// One place for every knob. Nothing downstream reads $env except the two
// signing nodes (which need the secret) — so the politeness caps below are the
// only thing standing between this workflow and a ban. Treat them as load-bearing.
//
// Requires on the n8n container:
//   NODE_FUNCTION_ALLOW_BUILTIN=crypto      (so the signing nodes can require it)
//   N8N_BLOCK_ENV_ACCESS_IN_NODE=false      (default; so $env works here)

const cfg = {
  // Our own app. No trailing slash.
  appBaseUrl: ($env.PRICE_WATCH_APP_URL || 'https://www.kitchen-appliances.co.uk').replace(/\/+$/, ''),

  // Machine key id. lib/machine-auth.ts only lets "collector" post observations.
  keyId: 'collector',

  // PriceSource.id row for Euronics. Created once in the admin; there is no
  // default, because guessing an id would file observations against the wrong
  // source and quietly change what the guards think they are looking at.
  sourceId: $env.PRICE_WATCH_EURONICS_SOURCE_ID || '',

  // ── Politeness. Hard caps, not suggestions. ──────────────────────────────
  // 40 products x 2 requests x ~10s mean delay ≈ 13 minutes of traffic, once a
  // night, from one IP. That is the load of a single slow human browsing.
  maxProducts: Number($env.PRICE_WATCH_MAX_PRODUCTS || 40),
  minDelayMs: Number($env.PRICE_WATCH_MIN_DELAY_MS || 6000),
  maxDelayMs: Number($env.PRICE_WATCH_MAX_DELAY_MS || 14000),
  requestTimeoutMs: 20000,

  // Identify ourselves honestly, with a way to be contacted or blocked. A
  // spoofed browser UA is what turns "a shop checking prices" into "a bot
  // evading detection", and that is the difference that matters if anyone asks.
  userAgent: $env.PRICE_WATCH_USER_AGENT
    || 'RuislipKitchenAppliancesPriceWatch/1.0 (+https://www.kitchen-appliances.co.uk/; ops@kitchen-appliances.co.uk)',

  origin: 'https://www.euronics.co.uk',
  searchBase: 'https://www.euronics.co.uk/search?text=',
};

if (!cfg.sourceId) {
  throw new Error('PRICE_WATCH_EURONICS_SOURCE_ID is not set. Create the Euronics PriceSource row in the admin and put its id in the n8n environment.');
}
if (!Number.isFinite(cfg.maxProducts) || cfg.maxProducts < 1 || cfg.maxProducts > 200) {
  throw new Error('PRICE_WATCH_MAX_PRODUCTS must be 1..200. Refusing to run an uncapped crawl.');
}
if (cfg.minDelayMs < 3000 || cfg.maxDelayMs < cfg.minDelayMs) {
  throw new Error('Refusing to run faster than one request per 3s. Raise PRICE_WATCH_MIN_DELAY_MS.');
}

// Run-scoped accumulator. Reset here on purpose: n8n persists static data
// between production executions, so last night's observations would otherwise
// be re-posted tonight.
const sd = $getWorkflowStaticData('global');
sd.observations = [];
sd.halt = null;
sd.startedAt = new Date().toISOString();

return [{ json: cfg }];

// ── Sign Worklist Request ────────────────────────────────────────────────────
// HMAC per lib/machine-auth.ts:
//   signature = hex( HMAC_SHA256( secret, `${timestamp}.${rawBody}` ) )
// GET has no body, so rawBody is the empty string — the route must read the raw
// body the same way (an absent body is "", not "null" and not "{}").
// The query string is NOT signed. It is a hint (limit/sourceId); the server
// decides the real worklist. Anything the server must trust goes in the body.

let crypto;
try {
  crypto = require('crypto');
} catch (e) {
  throw new Error('The Code node cannot require("crypto"). Set NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n container and restart it. See ops/n8n/README.md.');
}

const cfg = $input.first().json;

// PRICE_INGEST_SECRET_<KEYID_UPPERCASE_UNDERSCORED> — per key, no shared fallback.
const envName = 'PRICE_INGEST_SECRET_' + String(cfg.keyId).toUpperCase().replace(/[^A-Z0-9]/g, '_');
const secret = $env[envName];
if (!secret) {
  throw new Error('No secret in environment variable ' + envName + '. The server rejects unknown keys rather than allowing by default, so the run would 401.');
}

const timestamp = String(Math.floor(Date.now() / 1000));
const rawBody = '';
const signature = crypto
  .createHmac('sha256', secret)
  .update('worklist.' + timestamp + '.' + rawBody, 'utf8')
  .digest('hex');

const url = cfg.appBaseUrl
  + '/api/price-ingest/worklist'
  + '?limit=' + encodeURIComponent(cfg.maxProducts)
  + '&source=' + encodeURIComponent(cfg.sourceId);

return [{ json: { ...cfg, url, timestamp, signature } }];

// ── Worklist To Items ────────────────────────────────────────────────────────
// Turns the worklist response into one n8n item per product.
// Expected row shape (whatever /api/price-ingest/worklist returns, it must have
// at least these two): { productId, productCode, brand?, title?, priceNow? }

const cfg = $('Run Config').first().json;
const res = $input.first().json;

// fullResponse:true + neverError:true, so a bad status arrives as data, not a
// thrown HTTP error. Fail loudly here — a silent empty worklist looks exactly
// like "no products need checking", which is the wrong thing to believe.
if (res && res.statusCode !== undefined && res.statusCode !== 200) {
  throw new Error('worklist HTTP ' + res.statusCode + ': ' + String(res.body).slice(0, 300));
}

// Depending on the HTTP node's fullResponse setting, the payload is either at
// res.body or IS res. Accept both — a shape assumption here fails the whole run
// after auth has already succeeded, which is the most confusing place to break.
// The HTTP node hands the payload back under .body, .data, or as the item
// itself depending on its response settings. Accept all three: guessing one
// shape produced a SILENT zero-item run that still reported success.
let body = res;
if (res && res.body !== undefined) body = res.body;
else if (res && res.data !== undefined) body = res.data;
if (typeof body === 'string') {
  try { body = JSON.parse(body); }
  catch (e) { throw new Error('worklist returned non-JSON: ' + String(res.body).slice(0, 200)); }
}

const rows = Array.isArray(body) ? body : ((body && (body.products || body.items || body.worklist)) || []);
if (!Array.isArray(rows)) {
  throw new Error('worklist JSON has no array of products. Got keys: ' + Object.keys(body || {}).join(','));
}

const usable = rows.filter((r) => r && r.productId && r.productCode);
const skipped = rows.length - usable.length;

// The cap is applied here as well as server-side. Two independent caps, because
// a bug in either one otherwise turns into an uncapped crawl of someone's site.
const capped = usable.slice(0, cfg.maxProducts);

return capped.map((r, i) => ({
  json: {
    productId: r.productId,
    productCode: String(r.productCode),
    brand: r.brand || '',
    title: r.title || '',
    currentPrice: (r.priceNow === undefined ? null : r.priceNow),
    _index: i + 1,
    _total: capped.length,
    _skippedNoCode: skipped,
  },
}));

// ── Polite Delay ─────────────────────────────────────────────────────────────
// Runs at the top of every loop iteration, so it is also the cheapest place to
// enforce the halt. Randomised, not fixed: a request exactly every 10.000s is a
// signature, and it is also worse for the source (predictable bursts).
//
// If your n8n build blocks setTimeout in the Code node, replace this node with
// n8n-nodes-base.wait — you lose the jitter, so lower the rate to compensate.

const cfg = $('Run Config').first().json;
const sd = $getWorkflowStaticData('global');

if (sd.halt) {
  throw new Error('Run halted before this request: ' + sd.halt);
}

const span = Math.max(1, cfg.maxDelayMs - cfg.minDelayMs);
const waitMs = cfg.minDelayMs + Math.floor(Math.random() * span);
await new Promise((resolve) => setTimeout(resolve, waitMs));

return $input.all().map((item) => ({ json: { ...item.json, _waitedMs: waitMs } }));

// ── Parse Search HTML ────────────────────────────────────────────────────────
// Finds the first Euronics product link in a search results page.
// Verified shape (2026-08): /catalogue/<dept>/<cat>/<sub>/<slug>/p/<SKU>
// e.g. /catalogue/refrigeration/fridge-freezers/freestanding-fridge-freezers/
//      beko-ccfm4552w-54cm-5050-frost-free-fridge-freezer-white/p/BEKCCFM4552W
//
// Nothing here throws. Every failure becomes a status the server can store —
// "not_found" and "parse_failed" are data, and silently dropping them is how a
// price watcher ends up reporting on 6 of 40 products and nobody notices.

const sd = $getWorkflowStaticData('global');
const p = $('Polite Delay').first().json;
const res = $input.first().json;

const status = res.statusCode;
// The HTTP node returns the page under .body or .data depending on its
// response settings; reading only .body silently yielded an empty string
// and every product came back 'parse_failed' with the fetch actually fine.
const raw = (res && typeof res.body === 'string') ? res.body
  : (res && typeof res.data === 'string') ? res.data
  : (typeof res === 'string') ? res : '';
const html = raw;

const base = {
  productId: p.productId,
  productCode: p.productCode,
  title: p.title,
  currentPrice: p.currentPrice,
  searchUrl: res.url || '',
  pdpUrl: '',
  matchConfidence: 0,
  blocked: false,
  status: 'ok',
  note: '',
  httpStatus: status,
};

// 403 = Cloudflare. 429/503 = we are being rate limited or shed. All three mean
// stop, not retry: continuing is how a soft block becomes a permanent one.
if (status === 403 || status === 429 || status === 503) {
  sd.halt = 'Euronics search returned HTTP ' + status + ' on ' + p.productCode + ' — run stopped early to avoid a ban.';
  return [{ json: { ...base, blocked: true, status: 'blocked', note: 'search HTTP ' + status } }];
}
if (status !== 200) {
  return [{ json: { ...base, status: 'not_found', note: 'search HTTP ' + status } }];
}
if (!html) {
  return [{ json: { ...base, status: 'parse_failed', note: 'search returned an empty body' } }];
}

// Cloudflare sometimes answers 200 with a challenge page. Treat it as blocked.
if (/cf-browser-verification|Checking your browser|__cf_chl_|Attention Required!/i.test(html)) {
  sd.halt = 'Euronics served a bot-challenge page (HTTP 200) on ' + p.productCode + ' — run stopped early.';
  return [{ json: { ...base, blocked: true, status: 'blocked', note: 'bot challenge page behind a 200' } }];
}

const linkRe = /href="(\/catalogue\/[^"?#]*?\/p\/[A-Za-z0-9._-]+)"/g;
const links = [];
let m;
while ((m = linkRe.exec(html)) !== null) {
  if (!links.includes(m[1])) links.push(m[1]);
  if (links.length >= 20) break;
}

if (!links.length) {
  return [{ json: { ...base, status: 'not_found', note: 'no /p/ link in search results for ' + p.productCode } }];
}

// Prefer a link whose SKU actually contains our product code (BEKCCFM4552W
// contains CCFM4552W). Falling back to "first result" is legitimate but much
// weaker, and the confidence we report has to say so — the guards use it.
const norm = (s) => String(s).toUpperCase().replace(/[^A-Z0-9]/g, '');
const code = norm(p.productCode);
const scored = links.map((href) => {
  const sku = norm(href.split('/p/').pop());
  return { href, sku, exact: code.length >= 4 && sku.includes(code) };
});
const hit = scored.find((s) => s.exact) || scored[0];

return [{
  json: {
    ...base,
    pdpUrl: hit.href,
    sku: hit.sku,
    matchConfidence: hit.exact ? 1 : 0.4,
    note: hit.exact
      ? 'SKU ' + hit.sku + ' contains product code ' + code
      : 'no SKU matched ' + code + '; took first of ' + links.length + ' results — low confidence',
  },
}];

// ── Extract Price ────────────────────────────────────────────────────────────
// PRIMARY  : the structured value embedded in the page — "price": "349.0"
// FALLBACK : the visible currency figure — £349.00
//
// The fallback is second for a reason. A PDP contains many £ figures: the was-
// price, finance-per-month, delivery, extended warranty, "customers also bought".
// Picking the first or the largest is a coin toss. So the fallback takes the
// *most frequently repeated* plausible figure (a current price is normally
// printed several times: header, sticky bar, basket panel) and reports lower
// confidence, because it genuinely is a weaker read.
//
// Verified against the live PDP on 2026-08-13:
//   /catalogue/.../beko-ccfm4552w-.../p/BEKCCFM4552W  ->  "price": "349.0"  and  £349.00

const sd = $getWorkflowStaticData('global');
const meta = $('Parse Search HTML').first().json;
const cfg = $('Run Config').first().json;
const res = $input.first().json;

const status = res.statusCode;
// The HTTP node returns the page under .body or .data depending on its
// response settings; reading only .body silently yielded an empty string
// and every product came back 'parse_failed' with the fetch actually fine.
const raw = (res && typeof res.body === 'string') ? res.body
  : (res && typeof res.data === 'string') ? res.data
  : (typeof res === 'string') ? res : '';
const html = raw;
const sourceUrl = cfg.origin + meta.pdpUrl;

const out = {
  productId: meta.productId,
  productCode: meta.productCode,
  sourceUrl,
  price: null,
  deliveryCost: null,   // Euronics does not state it on the PDP. null, never 0 —
                        // guards.evaluateGuards blocks on unknown_delivery, and
                        // pretending delivery is free is how a landed-price
                        // comparison silently becomes wrong.
  inStock: null,
  includesVat: true,    // UK retail display prices are inc-VAT.
  matchConfidence: meta.matchConfidence,
  blocked: false,
  status: 'ok',
  note: meta.note,
};

// Every non-blocked outcome is recorded here. The blocked ones are not: they
// exit to "Record Blocked And Halt", which records them and ends the run, so
// recording twice would double-post the same observation.
const record = (o) => {
  const rec = {
    productId: o.productId,
    price: o.price,
    deliveryCost: o.deliveryCost,
    inStock: o.inStock,
    includesVat: o.includesVat,
    sourceUrl: o.sourceUrl,
    matchConfidence: o.matchConfidence,
    status: o.status,
    note: String(o.note || '').slice(0, 480),
    observedAt: new Date().toISOString(),
  };
  sd.observations.push(rec);
  return [{ json: { ...rec, blocked: false, productCode: o.productCode } }];
};

if (status === 403 || status === 429 || status === 503) {
  sd.halt = 'Euronics PDP returned HTTP ' + status + ' on ' + meta.productCode + ' — run stopped early to avoid a ban.';
  return [{ json: { ...out, blocked: true, status: 'blocked', note: 'PDP HTTP ' + status } }];
}
if (/cf-browser-verification|Checking your browser|__cf_chl_|Attention Required!/i.test(html)) {
  sd.halt = 'Euronics served a bot-challenge page on the PDP for ' + meta.productCode + ' — run stopped early.';
  return [{ json: { ...out, blocked: true, status: 'blocked', note: 'bot challenge page on PDP' } }];
}
if (status === 404) {
  return record({ ...out, status: 'not_found', note: 'PDP 404 — search link is stale' });
}
if (status !== 200 || !html) {
  return record({ ...out, status: 'parse_failed', note: 'PDP HTTP ' + status });
}

const toNum = (s) => Number(String(s).replace(/,/g, ''));
const plausible = (n) => Number.isFinite(n) && n >= 1 && n <= 20000;

// ── PRIMARY: structured ─────────────────────────────────────────────────────
const structured = [];
const structRe = /"price"\s*:\s*"?([0-9][0-9,]{0,8}(?:\.[0-9]{1,2})?)"?/g;
let sm;
while ((sm = structRe.exec(html)) !== null) {
  const n = toNum(sm[1]);
  if (plausible(n)) structured.push(n);
}

// ── FALLBACK: visible currency ──────────────────────────────────────────────
const visible = [];
const moneyRe = /£\s?([0-9][0-9,]{0,8}(?:\.[0-9]{2})?)/g;
let vm;
while ((vm = moneyRe.exec(html)) !== null) {
  const n = toNum(vm[1]);
  if (plausible(n)) visible.push(n);
}
const counts = new Map();
for (const n of visible) counts.set(n, (counts.get(n) || 0) + 1);
let modal = null, modalCount = 0;
for (const [n, c] of counts) {
  if (c > modalCount) { modal = n; modalCount = c; }
}

let price = null;
let method = '';
let confidence = meta.matchConfidence;
const notes = [];

if (structured.length) {
  price = structured[0];
  method = 'structured';
  const distinct = [...new Set(structured)];
  if (distinct.length > 1) {
    confidence -= 0.15;
    notes.push('page carried ' + distinct.length + ' distinct "price" values (' + distinct.slice(0, 4).join('/') + '); took the first');
  }
  // Cross-check. If the printed £ figure agrees, that is real corroboration.
  if (modal !== null && Math.abs(modal - price) < 0.01) {
    notes.push('structured value corroborated by the printed £ figure');
  } else if (modal !== null) {
    confidence -= 0.2;
    notes.push('structured ' + price + ' disagrees with the most-printed £ figure ' + modal);
  }
} else if (modal !== null) {
  price = modal;
  method = 'regex-fallback';
  confidence -= 0.25;
  notes.push('no structured "price" on the page; fell back to the £ figure printed ' + modalCount + 'x out of ' + visible.length + ' £ figures');
} else {
  return record({ ...out, status: 'parse_failed', note: 'no structured "price" and no £ figure found on ' + sourceUrl });
}

// Stock. Absence of the phrase is not proof of stock, so only a positive match
// on an out-of-stock phrase sets false; otherwise stays null (= unknown).
let inStock = null;
if (/out of stock|sold out|currently unavailable|no longer available/i.test(html)) inStock = false;
else if (/in stock|add to (basket|cart)/i.test(html)) inStock = true;

return record({
  ...out,
  price,
  inStock,
  status: 'ok',
  matchConfidence: Math.max(0, Math.min(1, Number(confidence.toFixed(2)))),
  note: [meta.note, method + ': ' + price].concat(notes).filter(Boolean).join(' | '),
});

// ── Record Not Found ─────────────────────────────────────────────────────────
// The search ran, the source answered, and there was no product page for this
// code. That is a result worth storing: it tells the owner "we cannot benchmark
// this line", which is different from "we forgot to look".

const sd = $getWorkflowStaticData('global');
const src = $input.first().json;

const rec = {
  productId: src.productId,
  price: null,
  deliveryCost: null,
  inStock: null,
  includesVat: true,
  sourceUrl: src.searchUrl || '',
  matchConfidence: 0,
  status: src.status === 'parse_failed' ? 'parse_failed' : 'not_found',
  note: (src.note || 'no Euronics product page for ' + src.productCode).slice(0, 480),
  observedAt: new Date().toISOString(),
};

sd.observations.push(rec);
return [{ json: rec }];

// ── Record Blocked And Halt ──────────────────────────────────────────────────
// Reached from either the search branch or the PDP branch. This node does NOT
// loop back — it exits the loop straight into the flush, so whatever we already
// collected still gets posted, and then the run ends.
//
// Deliberately no retry, no backoff-and-continue. A 403 from Cloudflare is the
// source saying stop. Retrying is how a temporary block becomes a permanent one,
// and there is no price on this site worth losing access over.

const sd = $getWorkflowStaticData('global');
const src = $input.first().json;

const rec = {
  productId: src.productId,
  price: null,
  deliveryCost: null,
  inStock: null,
  includesVat: true,
  sourceUrl: src.sourceUrl || src.searchUrl || '',
  matchConfidence: 0,
  status: 'blocked',
  note: (src.note || 'blocked').slice(0, 480),
  observedAt: new Date().toISOString(),
};

sd.observations.push(rec);
if (!sd.halt) sd.halt = 'blocked on ' + src.productCode;

return [{ json: { ...rec, halted: sd.halt } }];

// ── Build Observation Batch ──────────────────────────────────────────────────
// Reached two ways: the loop finished normally, or "Record Blocked And Halt"
// jumped here. Both flush the same accumulator, so a halted run still posts
// what it managed to collect.
//
// The exact JSON string built here is what gets signed AND what gets sent. It
// must not be re-serialised downstream: the HMAC covers `${timestamp}.${rawBody}`
// byte for byte, so a re-stringify that reorders one key is a 401. That is why
// "POST Observations" sends contentType:"raw" rather than letting n8n build the
// body from a JSON field.

const cfg = $('Run Config').first().json;
const sd = $getWorkflowStaticData('global');

const all = Array.isArray(sd.observations) ? sd.observations : [];
const MAX = 500;
const observations = all.slice(0, MAX);
const dropped = all.length - observations.length;

const counts = observations.reduce((acc, o) => {
  acc[o.status] = (acc[o.status] || 0) + 1;
  return acc;
}, {});

const payload = {
  sourceId: cfg.sourceId,
  runStartedAt: sd.startedAt,
  runFinishedAt: new Date().toISOString(),
  halted: sd.halt || null,
  observations,
};

// An empty batch is still posted on purpose: it is the heartbeat that moves
// PriceSource.lastRunAt / lastRunStatus. A source that silently stops running
// looks identical to a source where nothing changed.
const rawBody = JSON.stringify(payload);

return [{
  json: {
    rawBody,
    count: observations.length,
    dropped,
    counts,
    halted: payload.halted,
    // TextEncoder, not Buffer — Buffer is not reliably exposed in the Code
    // node sandbox, and this figure is only for the run log.
    bytes: new TextEncoder().encode(rawBody).length,
  },
}];

// ── Sign Observations POST ───────────────────────────────────────────────────
// Same scheme as the worklist GET, but rawBody is now the JSON we are about to
// send. Signing the body — not just the timestamp — is the whole point: it is
// what stops anyone who sees one request from replaying it with different prices.
//
// Timestamp is generated here, immediately before the POST. lib/machine-auth.ts
// rejects anything more than 300s out, and a batch built at the top of a
// 15-minute run would already be stale.

let crypto;
try {
  crypto = require('crypto');
} catch (e) {
  throw new Error('The Code node cannot require("crypto"). Set NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n container and restart it. See ops/n8n/README.md.');
}

const cfg = $('Run Config').first().json;
const batch = $input.first().json;

const envName = 'PRICE_INGEST_SECRET_' + String(cfg.keyId).toUpperCase().replace(/[^A-Z0-9]/g, '_');
const secret = $env[envName];
if (!secret) {
  throw new Error('No secret in environment variable ' + envName + '.');
}

const timestamp = String(Math.floor(Date.now() / 1000));
const signature = crypto
  .createHmac('sha256', secret)
  .update('observations.' + timestamp + '.' + batch.rawBody, 'utf8')
  .digest('hex');

return [{
  json: {
    ...batch,
    url: cfg.appBaseUrl + '/api/price-ingest/observations',
    keyId: cfg.keyId,
    timestamp,
    signature,
  },
}];

// ── Run Summary ──────────────────────────────────────────────────────────────
// Last node. Clears the accumulator, then decides whether this execution counts
// as a success. Throwing here is intentional: a halted or rejected run must show
// as a FAILED execution in n8n so the operator's error workflow / email fires.
// A run that quietly ends green after being blocked is how you find out three
// weeks later that the prices are stale.

const sd = $getWorkflowStaticData('global');
const batch = $('Sign Observations Post').first().json;
const res = $input.first().json;

const summary = {
  startedAt: sd.startedAt,
  finishedAt: new Date().toISOString(),
  posted: batch.count,
  dropped: batch.dropped,
  byStatus: batch.counts,
  bytes: batch.bytes,
  ingestStatus: res.statusCode,
  ingestBody: typeof res.body === 'string' ? res.body.slice(0, 400) : res.body,
  halted: batch.halted,
};

const halt = sd.halt;
sd.observations = [];
sd.halt = null;

if (res.statusCode === 401 || res.statusCode === 403) {
  throw new Error('Ingest rejected the batch (HTTP ' + res.statusCode + '). Check PRICE_INGEST_SECRET_COLLECTOR, the container clock (the signature window is 300s), and that key "collector" is allowed on the observations route. Body: ' + JSON.stringify(summary.ingestBody));
}
if (res.statusCode < 200 || res.statusCode >= 300) {
  throw new Error('Ingest returned HTTP ' + res.statusCode + '. ' + JSON.stringify(summary.ingestBody));
}
if (halt) {
  throw new Error('Run stopped early and its partial results were posted. Reason: ' + halt);
}

return [{ json: summary }];
